/* eslint-disable */

export default {
  props: {
    ViewInfo: Object
  },
  data() {
    return {
      basePrice: "",
      monthlyDiscount: "",
      weeklyDiscount: "",
      checkbox: false,
      weekendprice: "",
      pricing: false,
      paymentupiid: "",
      maxChildren: "",
      maxAdults: "",
      numberofadults: 1,
      numberofchildren: 0,
      maxAdults: 10,
      maxChildren: 5,
      check_in_time: null,
      check_in: false,
      check_out_time: null,
      check_out: false
    };
  },
  mounted() {
    var abc = this.ViewInfo;
    if (this.ViewInfo) {
      this.basePrice = this.ViewInfo.cost;
      this.numberofadults = this.ViewInfo.allowed_guests.no_of_adults;
      this.numberofchildren = this.ViewInfo.allowed_guests.no_of_childrens;
      this.check_out_time = this.ViewInfo.entry_logs.check_out;
      this.check_in_time = this.ViewInfo.entry_logs.check_in;
      this.paymentupiid = this.ViewInfo.payment_upi_id;
      this.weekendprice = this.ViewInfo.weekend_price;
      this.weeklyDiscount = this.ViewInfo.discounts.weekly_discount;
      this.monthlyDiscount = this.ViewInfo.discounts.monthly_discount;
      this.pricing = this.ViewInfo.is_price_visible;
    }
  },
  watch: {
    checkbox(newValue) {
      if (!newValue) {
        this.weekendprice = "";
        this.weeklyDiscount = "";
        this.monthlyDiscount = "";
      }
    }
  },
  methods: {
    decreaseAdultCount() {
      if (this.numberofadults > 1) {
        this.numberofadults -= 1;
      }
    },
    increaseAdultCount() {
      if (this.numberofadults < this.maxAdults) {
        this.numberofadults += 1;
      }
    },
    decreaseChildrenCount() {
      if (this.numberofchildren > 0) {
        this.numberofchildren -= 1;
      }
    },
    increaseChildrenCount() {
      if (this.numberofchildren < this.maxChildren) {
        this.numberofchildren += 1;
      }
    },
    is_number(evt) {
      evt = evt || window.event;
      let charCode = evt.which || evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      }
    },
    async emit_fourth_step() {
      const valid = await this.$refs.form.validate();
      if (!valid) return;
      var StepfourData = {
        weeklyprice: this.basePrice,
        specialPrice: this.checkbox ? this.weekendprice : null,
        weeklyDiscount: this.checkbox ? this.weeklyDiscount : null,
        monthlyDiscount: this.checkbox ? this.monthlyDiscount : null,
        numberofadults: this.numberofadults,
        numberofchildren: this.numberofchildren,
        payment_uip_Id: this.paymentupiid,
        check_in: this.check_in_time,
        chech_out: this.check_out_time,
        pricing: this.pricing
      };
      // console.log("emitfifthstep", StepfourData);
      this.$emit("emitfifthstep", StepfourData);
    },
    back_action() {
      this.$emit("emitfourthstep", 3);
    }
  }
};
